#!/bin/bash
CONFIG_FILE="${1:-sentinel.conf}"; [ -f "$CONFIG_FILE" ] || { echo "Error: configuration file not found" >&2; exit 1; }; source "$CONFIG_FILE"; declare -p SERVICES FILES_TO_WATCH >/dev/null 2>&1 || { echo "Error: required configuration variables are missing" >&2; exit 1; }; check_services() { for svc in "${SERVICES[@]}"; do if pgrep -f "$svc" >/dev/null; then echo "OK: $svc is running"; else if eval "$svc" >/dev/null 2>&1; then echo "FIXED: Restarted $svc"; else echo "ERROR: Failed to restart $svc"; fi; fi; done; }; check_services